using System;
using System.Drawing;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace AsterHand {
    internal sealed partial class MainForm {
        Label chatgptStatus;ComboBox accountPicker,modelPicker;
        bool loadingAi;string editingProvider;
        void BuildAiPage(FlowLayoutPanel page) {
            var card=Card("AI 服务",700);var provider=new ComboBox{FlatStyle=FlatStyle.Flat,DropDownStyle=ComboBoxStyle.DropDownList,Width=350,AccessibleName=T("AI 服务"),Margin=new Padding(4,6,4,12)};
            provider.Items.Add(new Choice("chatgpt","ChatGPT"));provider.Items.Add(new Choice("compatible",T("通用 API")));provider.SelectedIndex=J.Str(vault.State,"provider")=="chatgpt"?0:1;card.Controls.Add(provider);
            var fields=Flow(true);card.Controls.Add(fields);page.Controls.Add(card);
            Action render=null;render=()=>{loadingAi=true;editingProvider=((Choice)provider.SelectedItem).Id;bool isChat=editingProvider=="chatgpt";foreach(Control c in fields.Controls.Cast<Control>().ToArray())c.Dispose();fields.Controls.Clear();var settings=J.Get(vault.State,isChat?"chatgptSettings":"genericApi");
                TextBox apiBase=null,key=null;ComboBox protocol=null;
                if(isChat) {
                    chatgptStatus=L(chatAuth.Selected==null?"尚未登录 ChatGPT。":ChatGPTAuth.PlanEnabled(chatAuth.Selected)?"已登录 ChatGPT · 使用 ChatGPT 套餐":"已登录 ChatGPT · 尚未授权套餐用量",10);fields.Controls.Add(chatgptStatus);
                    accountPicker=new ComboBox{FlatStyle=FlatStyle.Flat,DropDownStyle=ComboBoxStyle.DropDownList,Width=410,Margin=new Padding(4,6,4,10),AccessibleName=T("ChatGPT 账户")};
                    foreach(var p in chatAuth.Profiles)accountPicker.Items.Add(new Choice(J.Str(p,"id"),J.Str(p,"email",J.Str(p,"name","ChatGPT"))));for(int i=0;i<accountPicker.Items.Count;i++)if(((Choice)accountPicker.Items[i]).Id==J.Str(vault.State,"selectedChatgpt"))accountPicker.SelectedIndex=i;
                    fields.Controls.Add(accountPicker);if(chatAuth.Selected!=null&&!ChatGPTAuth.PlanEnabled(chatAuth.Selected))fields.Controls.Add(B("启用 ChatGPT 套餐用量",()=>BeginSignIn(false,true),true,226));var authButtons=Flow();authButtons.Controls.Add(B("Continue with ChatGPT",()=>BeginSignIn(false),true,226));authButtons.Controls.Add(B("添加账户",()=>BeginSignIn(true),false,110));authButtons.Controls.Add(B("退出登录",()=>Async(async()=>{if(job!=null)throw new Exception("请先停止当前 AI 任务");var current=chatAuth.Selected;if(current==null)return;if(MessageBox.Show(this,T("断开 ChatGPT 登录？"),"AsterHand",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;string signOutStatus=await chatAuth.SignOut(J.Str(current,"id"),CancellationToken.None);MessageBox.Show(this,T(signOutStatus),"AsterHand");render();}),false,110));fields.Controls.Add(authButtons);
                    var fallback=Flow();fallback.Controls.Add(B("复制登录链接",()=>{chatAuth.Begin(false,false);Clipboard.SetText(chatAuth.AuthorizationUrl);chatgptStatus.Text=T("登录链接已复制，请在官方页面完成授权。");},false,150));fallback.Controls.Add(B("粘贴回调完成登录",()=>{string callback=Prompt("完成 ChatGPT 登录","粘贴官方返回的完整回调地址","");if(callback==null)return;Async(async()=>{await chatAuth.Complete(callback,CancellationToken.None);OnSignedIn("ChatGPT 登录成功。");});},false,170));fallback.Controls.Add(B("取消登录",()=>{chatAuth.Cancel();chatgptStatus.Text=T("已取消登录。");},false,100));fields.Controls.Add(fallback);fields.Controls.Add(L("仅账户登录会打开默认浏览器，授权后返回原生程序。",9));
                    fields.Controls.Add(B("管理 ChatGPT 用量",()=>OpenOfficialUrl("https://chatgpt.com/#settings/Usage"),false,190));
                } else {
                    fields.Controls.Add(L("API 地址",10));apiBase=Field(J.Str(settings,"apiBase","https://api.openai.com/v1"));apiBase.AccessibleName=T("API 地址");apiBase.Width=560;fields.Controls.Add(apiBase);
                    fields.Controls.Add(L("API Key（留空保留已保存的密钥）",10));key=Field("",true);key.AccessibleName="API Key";fields.Controls.Add(key);
                    fields.Controls.Add(L("接口格式",10));protocol=new ComboBox{FlatStyle=FlatStyle.Flat,DropDownStyle=ComboBoxStyle.DropDownList,Width=350,Margin=new Padding(4,6,4,12)};protocol.Items.Add(new Choice("auto",T("自动")));protocol.Items.Add(new Choice("chat","Chat Completions"));protocol.Items.Add(new Choice("responses","Responses"));for(int i=0;i<protocol.Items.Count;i++)if(((Choice)protocol.Items[i]).Id==J.Str(settings,"apiProtocol","auto"))protocol.SelectedIndex=i;fields.Controls.Add(protocol);fields.Controls.Add(L("兼容 OpenAI 格式；本机模型允许使用 HTTP，其他地址使用 HTTPS。",9));
                }
                fields.Controls.Add(L("模型",10));modelPicker=new ComboBox{FlatStyle=FlatStyle.Flat,Width=420,DropDownStyle=isChat?ComboBoxStyle.DropDownList:ComboBoxStyle.DropDown,Margin=new Padding(4,6,4,12),AccessibleName=T("模型")};PopulateModels(modelPicker,settings,J.Str(settings,"model"));fields.Controls.Add(modelPicker);
                fields.Controls.Add(L("推理深度",10));var effort=new ComboBox{FlatStyle=FlatStyle.Flat,Width=350,DropDownStyle=ComboBoxStyle.DropDownList,Margin=new Padding(4,6,4,12)};foreach(string x in new[]{"auto","low","medium","high","xhigh"})effort.Items.Add(new Choice(x,T(x=="auto"?"自动":x=="low"?"低":x=="medium"?"中":x=="high"?"高":"超高")));for(int i=0;i<effort.Items.Count;i++)if(((Choice)effort.Items[i]).Id==J.Str(settings,"effort","auto"))effort.SelectedIndex=i;fields.Controls.Add(effort);
                var status=L("模型列表从当前账户或 API 获取，不内置固定版本。",9);
                Action save=()=>{if(loadingAi)return;var previous=J.Map(J.Get(vault.State,isChat?"chatgptSettings":"genericApi"));string model=SelectedModel(modelPicker);var next=J.Read(J.Write(previous));next["model"]=model;next["effort"]=((Choice)effort.SelectedItem).Id;if(!isChat){Net.Api(apiBase.Text,"models");next["apiBase"]=apiBase.Text.Trim().TrimEnd('/');next["apiProtocol"]=((Choice)protocol.SelectedItem).Id;next["key"]=key.Text.Length>0?key.Text:J.Str(previous,"key");key.Clear();}lock(vault.Sync){vault.State[isChat?"chatgptSettings":"genericApi"]=next;vault.State["provider"]=editingProvider;vault.Save();}status.Text=T("已保存");};
                var buttons=Flow();buttons.Controls.Add(B("保存 AI 设置",save,true,130));buttons.Controls.Add(B("刷新模型列表",()=>Async(async()=>{save();status.Text=T("正在连接…");var options=AiSettings.Options(vault);var response=await agent.Request(options,null,"models",CancellationToken.None);var models=AiSettings.Models(response,isChat);if(models.Count==0)throw new Exception("当前账户或 API 没有返回可用模型。");if(fields.IsDisposed||editingProvider!=(isChat?"chatgpt":"compatible"))return;var next=J.Map(J.Get(vault.State,isChat?"chatgptSettings":"genericApi"));next["models"]=models;next["modelsFetchedAt"]=J.Now;PopulateModels(modelPicker,next,J.Str(next,"model"));next["model"]=SelectedModel(modelPicker);vault.Save();status.Text=T("模型列表已更新")+" · "+models.Count;}),false,140));fields.Controls.Add(buttons);fields.Controls.Add(status);
                if(isChat)accountPicker.SelectedIndexChanged+=(s,e)=>{if(loadingAi||accountPicker.SelectedItem==null)return;if(job!=null){Error(new Exception("请先停止当前 AI 任务"));return;}chatAuth.Select(((Choice)accountPicker.SelectedItem).Id);lock(vault.Sync){vault.State["chatgptSettings"]=J.Obj("model","","models",new object[0],"effort",J.Str(J.Get(vault.State,"chatgptSettings"),"effort","auto"));vault.Save();}render();Async(RefreshChatGPTModels);};loadingAi=false;if(Design.IsDpiReady(fields))Design.ApplyDpi(fields);
            };
            provider.SelectedIndexChanged+=(s,e)=>{if(loadingAi)return;vault.State["provider"]=((Choice)provider.SelectedItem).Id;vault.Save();render();};render();
        }
        static string SelectedModel(ComboBox picker) {var selected=picker.SelectedItem as Choice;return selected!=null?selected.Id:picker.Text.Trim();}
        void PopulateModels(ComboBox picker,object settings,string selected) {picker.Items.Clear();foreach(var m in J.List(J.Get(settings,"models")))picker.Items.Add(new Choice(J.Str(m,"id"),J.Str(m,"name",J.Str(m,"id"))));for(int i=0;i<picker.Items.Count;i++)if(((Choice)picker.Items[i]).Id==selected)picker.SelectedIndex=i;if(picker.SelectedIndex<0){if(picker.DropDownStyle==ComboBoxStyle.DropDown)picker.Text=selected;else if(picker.Items.Count>0)picker.SelectedIndex=0;}}
        void OpenOfficialUrl(string url) {Uri u;if(!Uri.TryCreate(url,UriKind.Absolute,out u)||u.Scheme!="https"||u.Host!="auth.openai.com"&&u.Host!="chatgpt.com")throw new Exception("官方授权地址无效。");System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(url){UseShellExecute=true});}
        void BeginSignIn(bool fresh,bool requestConsent=false) {if(job!=null)throw new Exception("请先停止当前 AI 任务");string url=chatAuth.Begin(fresh,true,requestConsent);if(chatgptStatus!=null&&!chatgptStatus.IsDisposed)chatgptStatus.Text=T("请在默认浏览器完成官方授权…");OpenOfficialUrl(url);}
        void OnSignedIn(string message) {Ui(()=>{if(chatgptStatus!=null&&!chatgptStatus.IsDisposed)chatgptStatus.Text=T(message);if(chatAuth.Selected==null)return;vault.State["provider"]="chatgpt";vault.State["chatgptSettings"]=J.Obj("model","","models",new object[0],"effort",J.Str(J.Get(vault.State,"chatgptSettings"),"effort","auto"));vault.Save();if(page=="settings")Navigate("settings");Async(RefreshChatGPTModels);});}
        async Task RefreshChatGPTModels() {if(!ChatGPTAuth.PlanEnabled(chatAuth.Selected))return;var options=AiSettings.Options(vault);options["provider"]="chatgpt";options["profileId"]=J.Str(chatAuth.Selected,"id");var result=await agent.Request(options,null,"models",CancellationToken.None);var models=AiSettings.Models(result,true);if(models.Count==0)throw new Exception("当前账户没有返回可用模型。");if(J.Str(chatAuth.Selected,"id")!=J.Str(options,"profileId"))return;var settings=J.Map(J.Get(vault.State,"chatgptSettings"));settings["models"]=models;settings["modelsFetchedAt"]=J.Now;if(!models.Any(m=>J.Str(m,"id")==J.Str(settings,"model")))settings["model"]=J.Str(models[0],"id");vault.State["chatgptSettings"]=settings;vault.Save();if(page=="settings")Navigate("settings");}
    }
}
